export function bannerDimensions(width,height){if(!Number.isFinite(width)||!Number.isFinite(height)||width<1||height<1||width*height>50000000)throw new Error('ภาพมีขนาดใหญ่เกินไป กรุณาเลือกภาพเล็กลง');const scale=Math.min(1,1920/width,1080/height);return {width:Math.max(1,Math.round(width*scale)),height:Math.max(1,Math.round(height*scale))}}
export function mountBannerImage(root,label){
 const wrapper=document.createElement('div');wrapper.innerHTML='<label></label><input type="file" accept="image/jpeg,image/png,image/webp"><img class="banner-preview" alt="ตัวอย่างแบนเนอร์" hidden><p class="sub" role="status"></p>';wrapper.querySelector('label').textContent=label;const input=wrapper.querySelector('input');input.id='banner-image-'+crypto.randomUUID();wrapper.querySelector('label').htmlFor=input.id;root.append(wrapper);
 let blob=null,processing=null,serial=0,previewUrl=null,disposed=false;const preview=wrapper.querySelector('img'),status=wrapper.querySelector('[role=status]');
 const revoke=()=>{if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null}};
 input.onchange=()=>{const version=++serial;blob=null;revoke();preview.hidden=true;const file=input.files[0];if(!file){processing=null;status.textContent='';return}processing=(async()=>{let url;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)throw new Error('ใช้ JPG, PNG หรือ WebP ไม่เกิน 15 MB');status.textContent='กำลังเตรียมภาพ…';url=URL.createObjectURL(file);const image=new Image();image.src=url;await image.decode();const size=bannerDimensions(image.naturalWidth,image.naturalHeight),canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,size.width,size.height);context.drawImage(image,0,0,size.width,size.height);const output=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!output||output.size>2*1024*1024)throw new Error('ภาพยังใหญ่เกินไป กรุณาเลือกภาพเล็กลง');if(disposed||version!==serial)return;blob=output;previewUrl=URL.createObjectURL(output);preview.src=previewUrl;preview.hidden=false;status.textContent='ภาพพร้อมบันทึก'}catch(error){if(!disposed&&version===serial)status.textContent=error.message;throw error}finally{if(url)URL.revokeObjectURL(url)}})();processing.catch(()=>{})};
 return {async value(){if(processing)await processing;return blob},disable:value=>input.disabled=value,dispose(){disposed=true;serial++;revoke()}};
}
